Method.Source:
/// <summary>
/// Get drawing request (identNo is now inventTable.NDXModelNumber. we crete a new request, because it is easier then searching in the field for the correct value)
/// </summary>
/// <param name = "_inventTable">InventTable record</param>
/// <returns>Niedax.AzureServiceBus IRequest object</returns>
public Niedax.AzureServiceBus.ServiceBusRelay.IRequest get_ZeichnungsRequest(InventTable _inventTable)
{
    NDXTRUMPFIdentNo identNo;
    Niedax.TRUMPFRecordModel.TRUMPFArtikel artikel = new Niedax.TRUMPFRecordModel.TRUMPFArtikel();
    Niedax.AzureServiceBus.ServiceBusRelay.IRequest request = Niedax.TRUMPFRecordModel.TRUMPFADORequest::d365Request(artikel);

    request = next get_ZeichnungsRequest(_inventTable);

    identNo= _inventTable.NDXModelNumber;

    Niedax.RecordModel.RecordFilter filter = new Niedax.RecordModel.RecordFilter();
    filter.FieldName = 'Name';
    filter.FieldValue = identNo;
    filter.ConditionType = Niedax.RecordModel.SQLConditionType::eq;
    request.addFilter(filter);

    request.requestType = Niedax.AzureServiceBus.ServiceBusRelay.RequestType::DataImport;

    return request;
}
